190→
191→        writeln!(
192→            self.term,
193→            "    {}",
194→            b.apply_to("└────────────────────────────────────")
195→        )
196→        .ok();
197→
198→        if let Some(h) = hint {
199→            writeln!(self.term).ok();
200→            writeln!(
