749→                                    continue 'step_execution;
750→                                }
751→                                RecoveryAction::Fix(cmd) | RecoveryAction::CustomFix(cmd) => {
752→                                    if recovery::confirm_fix(ui, step_name, &cmd)? {
753→                                        let fix_ok =
754→                                            recovery::run_fix(&cmd, project_root, &step.env)?;
755→                                        if fix_ok {
756→                                            ui.message("    Fix command succeeded.");
757→                                        } else {
758→                                            ui.message("    Fix command failed.");
759→                                        }
760→                                        retry_count += 1;
761→                                        continue 'step_execution;
762→                                    } else {
763→                                        // User declined the fix — re-show recovery menu
764→                                        continue 'recovery_menu;
765→                                    }
766→                                }
767→                                RecoveryAction::Shell => {
768→                                    ui.message("    Dropping to debug shell (exit to return)...");
769→                                    crate::shell::debug::spawn_debug_shell(
770→                                        step_name,
771→                                        project_root,
772→                                        &step.env,
773→                                        global_env,
774→                                    )?;
775→                                    // After shell exit, re-show recovery menu
776→                                    continue 'recovery_menu;
777→                                }
778→                                RecoveryAction::Skip => {
779→                                    skipped_by_user = true;
780→                                    let mut r = result;
781→                                    r.recovery_detail =
782→                                        Some("skipped by user after failure".to_string());
783→                                    final_result = Some(r);
784→                                    break 'step_execution;
785→                                }
786→                                RecoveryAction::Abort => {
787→                                    workflow_aborted = true;
788→                                    let mut r = result;
789→                                    r.recovery_detail = Some("aborted by user".to_string());
790→                                    final_result = Some(r);
791→                                    break 'step_execution;
792→                                }
793→                            }
794→                        }
795→                    }
796→                    _ => {
797→                        final_result = Some(result);
798→                        break 'step_execution;
799→                    }
800→                }
801→            }
802→
803→            // Update progress bar
804→            ui.show_workflow_progress(index + 1, total, start.elapsed());
805→
806→            // Push the final result exactly once
807→            if let Some(result) = final_result {
808→                let status = result.status();
809→                results.push(result);
810→
811→                if status == StepStatus::Failed {
812→                    all_success = false;
813→                    // Skip does NOT add to failed_steps (user made active choice)
814→                    if !step.allow_failure && !skipped_by_user {
815→                        failed_steps.insert(step_name.clone());
816→                    }
817→                }
818→            }
819→
820→            // Abort: stop processing further steps
821→            if workflow_aborted {
822→                all_success = false;
823→                break;
824→            }
825→        }
826→
827→        // Finish progress bar
828→        ui.finish_workflow_progress();
829→
830→        let mut all_skipped: Vec<String> = skipped.into_iter().collect();
831→        all_skipped.extend(env_skipped);
832→
833→        Ok(WorkflowResult {
834→            workflow: workflow_name.to_string(),
835→            steps: results,
836→            skipped: all_skipped,
837→            duration: start.elapsed(),
838→            success: all_success,
839→            aborted: workflow_aborted,
840→        })
841→    }
842→
843→    /// Build the dependency graph for the given workflow.
844→    pub fn build_graph(&self, workflow: &str) -> Result<DependencyGraph> {
845→        let workflow_config = self.config.workflows.get(workflow).ok_or_else(|| {
846→            BivvyError::ConfigValidationError {
847→                message: format!("Unknown workflow: {}", workflow),
848→            }
849→        })?;
850→
851→        let mut builder = DependencyGraph::builder();
852→
853→        for step_name in &workflow_config.steps {
854→            let step =
855→                self.steps
856→                    .get(step_name)
857→                    .ok_or_else(|| BivvyError::ConfigValidationError {
858→                        message: format!(
859→                            "Workflow '{}' references unknown step '{}'",
860→                            workflow, step_name
861→                        ),
862→                    })?;
863→
864→            builder = builder.add_step(step_name.clone(), step.depends_on.clone());
865→        }
866→
867→        builder.build()
868→    }
869→}
