121→/// Ask user to confirm running a fix command before executing it.
122→pub fn confirm_fix(ui: &mut dyn UserInterface, step_name: &str, command: &str) -> Result<bool> {
123→    let prompt = Prompt {
124→        key: format!("confirm_fix_{}", step_name),
125→        question: format!("Run `{}`?", command),
126→        prompt_type: PromptType::Confirm,
127→        default: Some("yes".to_string()),
128→    };
129→
130→    let answer = ui.prompt(&prompt)?;
131→    Ok(answer.as_bool().unwrap_or(true))
132→}
133→
134→/// Execute a fix command with the step's environment and working directory.
135→pub fn run_fix(command: &str, project_root: &Path, env: &HashMap<String, String>) -> Result<bool> {
136→    let options = CommandOptions {
137→        cwd: Some(project_root.to_path_buf()),
138→        env: env.clone(),
139→        capture_stdout: false,
140→        capture_stderr: false,
141→        ..Default::default()
142→    };
143→
144→    let result = execute(command, &options)?;
145→    Ok(result.success)
146→}
